import base64
import gzip
import webview

HTML_GZIP_B64 = ""
HTML = gzip.decompress(base64.b64decode(HTML_GZIP_B64)).decode("utf-8")

if __name__ == "__main__":
    webview.create_window(
        "Upwork Proposal Intelligence Agent",
        html=HTML,
        width=1280,
        height=860,
        min_size=(900, 640),
        confirm_close=False,
    )
    webview.start(gui="edgechromium", private_mode=False)
